mapper.select:
SELECT 
  FROM ast05_tr_code a
 WHERE a.ast05_company_id = #{companyId}
   AND a.ast05_asset_type LIKE #{assetType}
   AND COALESCE(a.ast05_use_yn,'true') = 'true'
   AND ( a.ast05_tr_cd LIKE #{searchText} OR a.ast05_tr_nm LIKE #{searchText} )
   AND a.ast05_rcv_pay_cd LIKE #{rcvPayCode}
   AND COALESCE(a.ast05_finance_yn,'false') LIKE COALESCE(CAST(#{financeYn} AS VARCHAR),'%')
 ORDER BY a.ast05_tr_cd

SELECT 
  FROM ast05_tr_code a
 WHERE a.ast05_tr_code_id = #{trCodeId}

SELECT ast05_tr_code_id
  FROM ast05_tr_code
 WHERE ast05_company_id = #{companyId}
   AND ast05_tr_cd      = #{trCode}
 LIMIT 1

mapper.delete:
DELETE FROM ast05_tr_code
 WHERE ast05_company_id = #{companyId}
   AND ast05_tr_code_id IN
#{id}

DELETE FROM ast05_tr_code
 WHERE ast05_company_id = #{companyId}
   AND ast05_tr_cd      = #{trCode}
